function currentPart(s){return DATA.parts.find(p=>p.id===s.tentSelected[s.group]);}
function setGroup(mode,g){
 const s=states[mode];s.group=g;
 setPressed(s.panel,'.uv-groups [data-group]',b=>b.dataset.group===g);q(s.panel,'.body-content').hidden=g!=='body';q(s.panel,'.tent-content').hidden=g==='body';q(s.panel,'.head-atlas-pages').hidden=g!=='head';
 if(g==='body')refreshBody(mode);else{renderPartButtons(mode);refreshTent(mode);}
 applyRightAppearance(mode);

}
function renderPartButtons(mode){
 const s=states[mode],host=q(s.panel,'.tent-parts'),parts=s.group==='bottom'?DATA.parts.filter(p=>p.id==='B01'||p.id==='L01'):s.group==='head'?atlasParts(currentPart(s).atlas):DATA.parts.filter(p=>p.group===s.group&&p.id!=='L01');host.replaceChildren();
 parts.forEach(p=>{const b=button(p.id==='J01'?'J01 · 공통 하부와 두 촉수':p.id==='L01'?'L01 · 상단 마감':p.id==='B01'?'B01 · 몸통 하단 마감':p.id);b.dataset.id=p.id;b.style.setProperty('--color',p.color);b.title=p.id+' '+p.name;b.setAttribute('aria-label',b.title);b.onclick=()=>{s.tentSelected[s.group]=p.id;if(s.group==='head')s.headSelected[p.atlas]=p.id;s.detail='part';refreshTent(mode)};host.append(b)});
}
function selectHeadAtlas(mode,atlas){
 const s=states[mode];s.tentSelected.head=s.headSelected[atlas];renderPartButtons(mode);refreshTent(mode);
}
function selectBody(mode,kind,id){const s=states[mode];s.bodySelection=kind?{kind,id}:null;refreshBody(mode);}
function refreshBody(mode){const s=states[mode],p=s.panel,sel=s.bodySelection,map=q(p,'.uv-map');if(!map.querySelector('svg'))return;
 qa(p,'.body-part,.body-seam').forEach(b=>{const active=!!sel&&(sel.kind==='part'?b.classList.contains('body-part')&&b.dataset.part===sel.id:b.classList.contains('body-seam')&&b.dataset.seam===sel.id);b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});qa(map,'.seam').forEach(g=>g.classList.toggle('active',!!sel&&sel.kind==='seam'&&g.dataset.seam===sel.id));const path=q(map,'.connector');path.setAttribute('d','');let keep=null,text='';
 if(!sel)text='몸통 한 장 + 뒤쪽 중앙판 + 아래턱, 총 3묶음입니다. S 번호 또는 턱↔B01-F를 누르면 서로 맞대는 연결 경계가 강조됩니다.';
 else if(sel.kind==='part'){keep=[sel.id];text=sel.id+' · '+BODY_NAMES[sel.id]+'의 UV 구역을 강조했습니다.';}
 else{const seam=DATA.seams.find(x=>x.id===sel.id);keep=seam.parts;if(seam.kind==='jaw-bottom'){text='아래턱 U10·U11 하단의 강조된 경계와, 위에 표시된 B01-F 실제 UV 조각의 강조된 경계를 서로 포개 재봉합니다. 점선은 시작점↔시작점, 끝점↔끝점 대응을 표시합니다.';}else{const pts=DATA.labels.filter(x=>x.id===sel.id).map(x=>x.anchor);const [a,b]=pts,bend=(a[1]+b[1])/2;path.setAttribute('d',`M ${a[0]} ${a[1]} C ${a[0]} ${bend} ${b[0]} ${bend} ${b[0]} ${b[1]}`);text=sel.id+' : '+seam.parts[0]+' ↔ U09. 작은 원 시작점끼리, 화살표 끝점끼리 대응합니다.';}}
 const jawOn=!!sel&&sel.kind==='seam'&&sel.id===JAW_CONNECTION.id;qa(map,'.jaw-counterpart').forEach(g=>g.style.display=jawOn?'inline':'none');qa(map,'.jaw-map-start,.jaw-map-end').forEach(g=>g.style.display=jawOn?'inline':'none');qa(map,'.uv-face,.uv-merged-face').forEach(f=>f.style.opacity=!keep||keep.includes(f.dataset.part)?'1':'.14');q(p,'.body-status').textContent=text;
}
function rightVariantSuffix(s){return s.uvPalette+'-'+(s.uvLabels?'labels':'plain')+(s.uvWire?'':'-no-grid');}
function applyRightAppearance(mode){
 const s=states[mode],root=s.panel;setPressed(root,'.uv-appearance [data-uv-palette]',b=>b.dataset.uvPalette===s.uvPalette);const numberButton=q(root,'.uv-labels-toggle');numberButton.classList.toggle('active',s.uvLabels);numberButton.setAttribute('aria-pressed',String(s.uvLabels));numberButton.textContent=s.uvLabels?'✓ 번호표 켜짐':'번호표 꺼짐';
 const wireButton=q(root,'.uv-wire-toggle');wireButton.classList.toggle('active',s.uvWire);wireButton.setAttribute('aria-pressed',String(s.uvWire));wireButton.textContent=s.uvWire?'✓ 메시 선 켜짐':'메시 선 꺼짐';
 const map=q(root,'.uv-map');map.classList.toggle('hide-uv-labels',!s.uvLabels);map.classList.toggle('hide-uv-grid',!s.uvWire);qa(map,'.uv-face,.uv-merged-face').forEach(f=>{const fill=s.uvPalette==='actual'?'url(#body-actual-pattern-'+mode+')':DATA.colors[f.dataset.part];f.setAttribute('fill',fill)});
 const bodyLinks=qa(root,'.body-content .downloads a');bodyLinks[0].href='UV-body-'+rightVariantSuffix(s)+'.webp';bodyLinks[0].textContent='현재 모습 크게 보기 ↗';bodyLinks[1].textContent='기본 구분색 SVG';bodyLinks[2].href=s.uvPalette==='actual'?'UV-body-actual-fill-4096.png':'UV-connected-color-fill-4096.png';bodyLinks[2].textContent=s.uvPalette==='actual'?'실제 색상 PNG 원본':'번호 없는 구분색 PNG';
}
function refreshRightAppearance(mode){const s=states[mode];applyRightAppearance(mode);if(s.group!=='body')refreshTent(mode,false);}
function refreshTent(mode,updateModel=true){
 const s=states[mode];if(s.group==='body')return;const p=currentPart(s),root=s.panel,atlasKey=p.atlas||s.group;
 setPressed(root,'.tent-parts [data-id]',b=>b.dataset.id===p.id);setPressed(root,'[data-detail]',b=>b.dataset.detail===s.detail);setPressed(root,'.atlas-page-buttons [data-atlas]',b=>b.dataset.atlas===atlasKey);
 const joined=p.id==='J01',atlasTitle=p.atlas==='lower-connection'?'B01 몸통 마감 ↔ L01 하부 마감':joined?'공통 하부 UV 전체':s.group==='long'?'큰 촉수 UV 묶음6개':s.group==='head'?'머리 가시 '+atlasLabel(atlasKey)+' · UV':GROUPS[s.group]+' · UV 배치 전체';
 const pageTitle=atlasTitle;q(root,'[data-detail=atlas]').textContent=s.group==='long'?atlasTitle:'그룹 UV 전체';
 const notes=[joined?'J01은 공통 하부에서 굵은 두 촉수와 휘어진 끝까지 이어지는 한 부품입니다. F 앞면과 B 뒷면의 대응 번호를 UV에서 대조하세요.':'UV에 표시된 같은 연결 번호와 경계끼리 대조하세요.'];
 if(p.attachments.length&&p.id!=='B01'&&p.id!=='L01'){const targets=[...new Set(p.attachments.flatMap(a=>a.targets))].map(id=>({BODY:'몸통',JAW:'아래턱',PROXY:'상단 마감면'})[id]||id);notes.push('D는 닫힌 마감·접촉면입니다. 펼친 모양과 재봉 경계를 대조하세요.'+(targets.length?' 맞닿는 부품·위치: '+targets.join(' · ')+'.':'')+' 몸통에는 새 구멍을 내지 않습니다.');}
 if(p.assembly.length)notes.push('촉수끼리 잇는 열린 재봉 경계: '+p.assembly.map(a=>a.id+(a.parts.length?' ('+a.parts.join(' ↔ ')+')':'')).join(', ')+'.');
 if(joined)notes.push('착용 공간은 실측 검증 전입니다.');
 q(root,'.tent-note').textContent=p.note||notes.join(' ');
 q(root,'.part-name').textContent=s.detail==='part'?p.id+' · '+p.name:pageTitle;
 const suffix=rightVariantSuffix(s),card='card-'+p.id+'-'+suffix+'.webp',atlas='UV-'+atlasKey+'-'+suffix+'.webp';
 q(root,'.tent-card-img').src=card;q(root,'.tent-card-img').alt=p.id+' '+p.name+' 모델과 UV 대조';q(root,'.tent-card-link').href=card;q(root,'.tent-card-link').hidden=s.detail!=='part';
 q(root,'.tent-atlas-img').src=atlas;q(root,'.tent-atlas-img').alt=pageTitle;q(root,'.tent-atlas-link').href=atlas;q(root,'.tent-atlas-link').hidden=s.detail!=='atlas';
 q(root,'.tent-download-png').href=atlas;q(root,'.tent-download-png').textContent='현재 UV 크게 보기 ↗';q(root,'.tent-download-svg').href='Tentacles-'+atlasKey+'-UV-guide.svg';q(root,'.tent-download-svg').textContent='기본 구분색 SVG';q(root,'.tent-download-fill').href=s.uvPalette==='actual'?'UV-'+atlasKey+'-actual-fill-4096.png':'Tentacles-'+atlasKey+'-color-fill-4096.png';q(root,'.tent-download-fill').textContent=s.uvPalette==='actual'?'실제 색상 PNG 원본':'번호 없는 구분색 PNG';q(root,'.tent-download-card').href=card;

}

